typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;
typedef unsigned long u_long;
typedef unsigned long long u_long128 __attribute__((mode(TI)));

struct TIM2_PICTUREHEADER;
struct nglFileBuf { u_char* Buf; u_int Size; u_int UserData; };
struct nglFixedString { char data[32]; } __attribute__((aligned(8)));

class nglTexStreamPos {
public:
  u_int addr, cycle;
};

struct nglTexGsChunk
{
  u_char PSM;
  u_char TBW;
  u_short Offset;
  u_short Size;
  u_int* DMA;
  void* Data;
};

struct nglTexture
{
  nglTexStreamPos TexStreamPos;
  u_short Width, Height;
  u_int Hash;
  u_char Type;
  u_char TW, TH;
  struct {
    u_int LoadedInPlace : 1;
    u_int Locked : 1;
    u_int VRAMOnly : 1;
    u_int System : 1;
    u_int RenderTarget : 1;
  } Flags;
  TIM2_PICTUREHEADER *ph;
  u_int Format;
  u_int* Data;
  u_int NFrames;
  nglTexture** Frames;
  u_int SrcDataSize;
  nglFileBuf FileBuf;
  nglFixedString FileName;
  u_int GsBaseTBP;
  u_int GsSize;
  u_int* DMAMem;
  u_int ClutColors;
  nglTexGsChunk GsClut;
  u_int MipMapTextures;
  nglTexGsChunk GsImage[7];
  u_long GsTexA;
  u_long GsTex0;
  u_long GsTex1;
  u_long GsMipTBP1;
  u_long GsMipTBP2;
  float InvHypot;
  u_int MipMapInitCount;
  u_int MipMapFirstLod;
};

struct nglPerfInfoStruct { char padding[56]; u_int BakedTextureDMASize; };

extern u_char* nglGifPacketWork;
extern nglPerfInfoStruct nglPerfInfo;
extern "C" void nglBakeTextureChunk(u_long*&, int, int, int, int, u_long128*) __asm__("nglBakeTextureChunk__FRPUliiiiPUx");
extern "C" int nglTim2CalcBufWidth(int, int) __asm__("nglTim2CalcBufWidth__Fii");
extern "C" int nglTim2CalcBufSize(int, int, int) __asm__("nglTim2CalcBufSize__Fiii");
extern "C" void* nglMemAlloc(u_int, u_int = 128) __asm__("nglMemAlloc__FUiUi");
extern "C" void* memcpy(void*, const void*, u_int);

__asm__(".equ nglGifPacketWork,0x004AEF34");
__asm__(".equ nglPerfInfo,0x004ACA18");
__asm__(".equ nglBakeTextureChunk__FRPUliiiiPUx,0x0039DC40");
__asm__(".equ nglTim2CalcBufWidth__Fii,0x0039D9F8");
__asm__(".equ nglTim2CalcBufSize__Fiii,0x0039DAB0");
__asm__(".equ nglMemAlloc__FUiUi,0x00395D10");

void nglBakeTexture( nglTexture* Tex )
{
  u_long128 *pImage;

  u_long* Packet = (u_long*)nglGifPacketWork;
  u_int Offset = 0;

  u_int psm = Tex->GsImage[0].PSM;
  int width = Tex->Width;
  int height = Tex->Height;

  Tex->MipMapFirstLod = 0;
  Tex->MipMapInitCount = 0;

  if ( Tex->ClutColors )
  {
    Tex->GsClut.TBW = 1;
    Tex->GsClut.Offset = Offset;
    Tex->GsClut.DMA = (u_int*)Packet;

    pImage = (u_long128 *)Tex->GsClut.Data;
    if (pImage)
    {
      nglBakeTextureChunk( Packet, Tex->GsClut.PSM, 1, 16, Tex->ClutColors / 16, pImage );
      Offset += ( ( 4 * Tex->ClutColors ) + 255 ) / 256;
    }
  }

  if ( Tex->MipMapTextures > 1 )
  {
    for ( u_int i=Tex->MipMapTextures-1; i>=1; --i )
    {
      int w = width >> i;
      int h = height >> i;

      psm = Tex->GsImage[i].PSM;

      Tex->GsImage[i].TBW = nglTim2CalcBufWidth( psm, w );
      Tex->GsImage[i].Offset = Offset;
      Tex->GsImage[i].DMA = (u_int*)Packet;

      pImage = (u_long128*)Tex->GsImage[i].Data;
      if (pImage)
      {
        nglBakeTextureChunk( Packet, psm, Tex->GsImage[i].TBW, w, h, pImage );
        Offset += nglTim2CalcBufSize( psm, w, h );
      }
      Tex->GsImage[i].Size = Offset;
    }
  }
  else
    Tex->MipMapTextures = 0;

  pImage = (u_long128*)Tex->GsImage[0].Data;
  if (pImage)
  {
    Offset = (Offset+31)&~31;
  }
  Tex->GsImage[0].TBW = nglTim2CalcBufWidth( psm, width );
  Tex->GsImage[0].Offset = Offset;
  Tex->GsImage[0].DMA = (u_int*)Packet;

  if (pImage)
  {
    nglBakeTextureChunk( Packet, psm, Tex->GsImage[0].TBW, width, height, pImage );
    Offset += nglTim2CalcBufSize( psm, width, height );
  }

  Tex->GsImage[0].Size = Offset;
  Tex->GsSize = Tex->GsImage[0].Size;

  u_int Size = (u_int)Packet - (u_int)nglGifPacketWork;
  u_char* BakedDMA = (u_char*)nglMemAlloc( Size );
  memcpy( BakedDMA, nglGifPacketWork, Size );

  nglPerfInfo.BakedTextureDMASize += Size;
  Tex->DMAMem = (u_int *)BakedDMA;

#define PTR_OFFSET( Ptr ) { if ( Ptr ) Ptr = (u_int*)( (u_int)Ptr + ( (u_int)BakedDMA - (u_int)nglGifPacketWork ) ); }
  PTR_OFFSET( Tex->GsImage[0].DMA );
  if ( Tex->ClutColors )
    PTR_OFFSET( Tex->GsClut.DMA );
  for ( u_int i = 1; i < Tex->MipMapTextures; i++ )
    PTR_OFFSET( Tex->GsImage[i].DMA );
#undef PTR_OFFSET
}
